registry.content:
.df-alert {
  font-family: var(--df-font);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.7rem 0.9rem;
  border: 2px solid var(--df-ink);
  border-left-width: 6px;
  border-radius: var(--df-radius);
  background: var(--df-paper);
  box-shadow: var(--df-shadow-sm);
}
.df-alert--info { border-left-color: var(--df-primary); }
.df-alert--warn { border-left-color: var(--df-warn); }
.df-alert--bad  { border-left-color: var(--df-tertiary); }
.df-alert--ok   { border-left-color: var(--df-secondary); }

import * as React from "react";
import "./tokens.css";

export interface AlertProps extends React.HTMLAttributes<HTMLDivElement> {
  tone?: "info" | "warn" | "bad" | "ok";
}

/* alerta com borda dura — feedback de operação (preço, ban, erro) */
export function Alert({ tone = "info", className = "", children, ...props }: AlertProps) {
  return (
    <div role="alert" className={`df-alert df-alert--${tone} ${className}`.trim()} {...props}>
      {children}
    </div>
  );
}

.df-badge {
  display: inline-grid;
  place-items: center;
  min-width: 1.4rem;
  height: 1.4rem;
  padding: 0 0.35rem;
  font-family: var(--df-font);
  font-size: 0.72rem;
  font-weight: 800;
  border: 2px solid var(--df-ink);
  border-radius: 999px;
  background: var(--df-primary);
  color: var(--df-ink);
  box-shadow: var(--df-shadow-sm);
}
.df-badge--brand { background: var(--df-brand); color: #fff; }
.df-badge--warn  { background: var(--df-warn); }
.df-badge--bad   { background: var(--df-tertiary); color: #fff; }

import * as React from "react";
import "./tokens.css";

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: "primary" | "brand" | "warn" | "bad";
}

/* badge numerico (contador de tarefas, notificacoes) */
export function Badge({ tone = "primary", className = "", children, ...props }: BadgeProps) {
  return (
    <span className={`df-badge df-badge--${tone} ${className}`.trim()} {...props}>
      {children}
    </span>
  );
}

/* classes do df-btn — tokens em tokens.css */
.df-btn {
  --btn-bg: var(--df-paper);
  --btn-fg: var(--df-ink);
  font-family: var(--df-font);
  font-weight: 700;
  border: 2px solid var(--df-ink);
  border-radius: var(--df-radius);
  background: var(--btn-bg);
  color: var(--btn-fg);
  box-shadow: var(--df-shadow);
  cursor: pointer;
  transition: transform 80ms ease, box-shadow 80ms ease;
  line-height: 1;
}
.df-btn:hover { transform: translate(-1px, -1px); box-shadow: 0 5px 0 var(--df-ink); }
.df-btn:active { transform: translate(2px, 2px); box-shadow: none; }
.df-btn:focus-visible { outline: 3px solid var(--df-primary); outline-offset: 2px; }
.df-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; box-shadow: var(--df-shadow-sm); }

.df-btn--paper   { --btn-bg: var(--df-paper); }
.df-btn--primary { --btn-bg: var(--df-primary); }
.df-btn--brand   { --btn-bg: var(--df-brand); --btn-fg: #fff; }
.df-btn--danger  { --btn-bg: var(--df-tertiary); --btn-fg: #fff; }
.df-btn--ghost   { --btn-bg: transparent; box-shadow: none; }

.df-btn--sm { padding: 0.35rem 0.7rem; font-size: 0.8rem; }
.df-btn--md { padding: 0.55rem 1rem; font-size: 0.9rem; }
.df-btn--lg { padding: 0.8rem 1.4rem; font-size: 1.05rem; }

import * as React from "react";
import "./tokens.css";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "paper" | "primary" | "brand" | "danger" | "ghost";
  size?: "sm" | "md" | "lg";
}

/* neobrutal: borda 2px ink, sombra dura que "desloca" no hover/active */
export function Button({ variant = "paper", size = "md", className = "", ...props }: ButtonProps) {
  const base = [
    "df-btn",
    `df-btn--${variant}`,
    `df-btn--${size}`,
    className,
  ].join(" ");
  return <button className={base} {...props} />;
}

.df-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--df-font);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  padding: 0.25rem 0.6rem;
  border: 2px solid var(--df-ink);
  border-radius: 999px;
  background: var(--df-paper);
  color: var(--df-ink);
  box-shadow: var(--df-shadow-sm);
}
.df-chip__dot { width: 8px; height: 8px; border-radius: 50%; background: var(--df-border); }
.df-chip--ok   { background: var(--df-secondary); }
.df-chip--ok .df-chip__dot   { background: #065f46; }
.df-chip--warn { background: var(--df-warn); }
.df-chip--warn .df-chip__dot { background: #7c2d12; }
.df-chip--bad  { background: var(--df-tertiary); color: #fff; }
.df-chip--bad .df-chip__dot  { background: #7f1d1d; }
.df-chip--info { background: var(--df-paper); }
.df-chip--info .df-chip__dot { background: var(--df-primary); }

import * as React from "react";
import "./tokens.css";

export interface ChipProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: "ok" | "warn" | "bad" | "info";
  dot?: boolean;
}

/* chip de estado (preço ok, alerta, radar...) com dot de status */
export function Chip({ tone = "info", dot = false, className = "", children, ...props }: ChipProps) {
  return (
    <span className={`df-chip df-chip--${tone} ${className}`} {...props}>
      {dot && <span className="df-chip__dot" aria-hidden />}
      {children}
    </span>
  );
}

.df-input {
  font-family: var(--df-font);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--df-ink);
  background: var(--df-paper);
  border: 2px solid var(--df-ink);
  border-radius: var(--df-radius);
  box-shadow: var(--df-shadow-sm);
  padding: 0.55rem 0.8rem;
  min-width: 0;
  width: 100%;
}
.df-input::placeholder { color: var(--df-dim); font-weight: 500; }
.df-input:focus-visible { outline: 3px solid var(--df-primary); outline-offset: 1px; }
.df-input--invalid { border-color: var(--df-tertiary); background: #fef2f2; }
.df-input:disabled { opacity: 0.5; cursor: not-allowed; }

import * as React from "react";
import "./tokens.css";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  invalid?: boolean;
}

export function Input({ invalid = false, className = "", ...props }: InputProps) {
  return (
    <input
      aria-invalid={invalid || undefined}
      className={`df-input ${invalid ? "df-input--invalid" : ""} ${className}`.trim()}
      {...props}
    />
  );
}
